import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Container for the node
  const root = new Group();

  // Geometry – a unit plane (will be scaled by the adapter if needed)
  const geometry = new PlaneGeometry(1, 1);

  // Basic material; texture will be applied asynchronously
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    depthWrite: false,
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture synchronously (promise resolves later)
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Handlers placeholder (no interactions defined)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose texture
    if (loadedTexture) {
      loadedTexture.dispose();
    }
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();

    // Kill any GSAP timelines that might have been created in the future
    if (root.userData._gsapTimeline) {
      root.userData._gsapTimeline.kill();
    }
  };

  return root;
}
